-- Reset the built-in (seeded) dashboards of two internal orgs — the owner's
-- operating org and the platform org — to the current shipped templates
-- (src/lib/reports/dashboard-templates.ts, getSeedableDashboardTemplates).
--
-- Why: both orgs were seeded Aug 29 – Sep 1 from older template versions that
-- later template changes never rewrote (old Sales Overview layout, payment
-- panels summing gross amount_cents instead of net cash, leads panels with an
-- old filter). Since the Advanced Reporting gate (#489), a built-in panel runs
-- without the add-on only when it exactly matches a shipped template panel, so
-- stale copies would show locked. Every other org's built-ins already match.
--
-- Only rows whose config differs from the template are touched (idempotent).
-- Name, description and config are reset; visible_to_crew and ids are kept.
-- The prior rows are copied to crm_dashboards_builtin_reset_bak_20261112
-- (RLS on, no policies: not reachable through the API) so the old layouts can
-- be restored. Drop that table once nobody needs them.
-- On databases without these orgs (TEST) this changes nothing.

create table if not exists public.crm_dashboards_builtin_reset_bak_20261112 as
  select * from public.crm_dashboards where false;
alter table public.crm_dashboards_builtin_reset_bak_20261112 enable row level security;
revoke all on public.crm_dashboards_builtin_reset_bak_20261112 from anon, authenticated;

create temp table _builtin_tpl (key text primary key, name text, description text, config jsonb);
insert into _builtin_tpl (key, name, description, config) values
