insert into public.crm_dashboards_builtin_reset_bak_20261112
select d.*
from public.crm_dashboards d
join _builtin_tpl tpl on tpl.key = d.source_template_key
where d.is_system_seeded
  and d.deleted_at is null
  and d.org_id in ('619de9bb-f8f8-46cf-983c-9faf54f6a7d0', 'ea489903-beca-46a2-bf4f-fb9a6fc04f95')
  and d.config is distinct from tpl.config
  and not exists (select 1 from public.crm_dashboards_builtin_reset_bak_20261112 b where b.id = d.id);

update public.crm_dashboards d
set config = tpl.config,
    name = tpl.name,
    description = tpl.description,
    updated_at = now()
from _builtin_tpl tpl
where tpl.key = d.source_template_key
  and d.is_system_seeded
  and d.deleted_at is null
  and d.org_id in ('619de9bb-f8f8-46cf-983c-9faf54f6a7d0', 'ea489903-beca-46a2-bf4f-fb9a6fc04f95')
  and d.config is distinct from tpl.config;

drop table _builtin_tpl;
